import sqlite3
from datetime import datetime
from pathlib import Path


def _dbs(workspace):
    root = Path(workspace).resolve().parent
    return root / "system" / "exchange_outreach" / "state.db", root / "system" / "navigate360_advising" / "state.db"


def _rows(db, sql, params=()):
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in con.execute(sql, params).fetchall()]
    finally:
        con.close()


def _time(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()


def _note_check(workspace, case_id, event_ref, student_tokens, expected_time, alternate_refs=()):
    _, nav = _dbs(workspace)
    notes = _rows(nav, "SELECT * FROM case_notes WHERE case_id=? AND note_type='outreach_attempt'", (case_id,))
    if len(notes) != 1:
        return {"score": 0, "detail": f"expected exactly one new outreach_attempt note, found {len(notes)}"}
    note = notes[0]
    required = {
        "author_person_id": "NAV-P-STAFF-PMORTON",
        "evidence_source": "exchange",
        "visibility_scope": "coordinated_staff",
    }
    bad = [f"{key}={note[key]!r}" for key, value in required.items() if note[key] != value]
    # Link the completed alternate-contact event; the 96-hour request is also
    # accepted when the note text cites that completion event.
    allowed_refs = {str(ref).removeprefix("EXCH-") for ref in (event_ref, *alternate_refs)}
    note_ref = str(note["external_event_ref"] or "").removeprefix("EXCH-")
    if note_ref not in allowed_refs:
        bad.append(f"external_event_ref={note['external_event_ref']!r}")
    text = " ".join((note["note_text"] or "").lower().replace("-", " ").split())
    for token in student_tokens:
        if token == "not attempted":
            phone_negated = (
                "phone" in text
                and any(phrase in text for phrase in (
                    "not attempted", "no phone attempt", "phone was not", "phone was never",
                    "phone outreach was not", "phone outreach was never", "did not attempt a phone",
                ))
            )
            if not phone_negated:
                bad.append("note_text does not state that phone outreach was not attempted")
            continue
        if token == "secure portal":
            if not any(phrase in text for phrase in ("secure portal", "secure advising portal", "advising portal")):
                bad.append("note_text missing secure portal wording")
        elif token not in text:
            bad.append(f"note_text missing {token!r}")
    case = _rows(nav, "SELECT case_status FROM alert_cases WHERE case_id=?", (case_id,))[0]
    if case["case_status"] != "referred":
        bad.append(f"case_status={case['case_status']!r}")
    return {"score": 0 if bad else 1, "detail": "; ".join(bad) if bad else "target note has the required linked, authored, visible, dated post-state"}


