    actual_refs = [(r["case_id"], r["referral_id"], r["destination_unit_id"], r["referral_type"], r["appointment_status"]) for r in referrals]
    bad = []
    if len(messages) != 79:
        bad.append(f"Exchange message count {len(messages)} != 79")
